package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;
import com.ferreteriahuaman.repository.*;
import com.ferreteriahuaman.dto.InventoryModels.*;
import com.ferreteriahuaman.dto.ProductModels.*;
import com.ferreteriahuaman.dto.PurchaseModels.*;
import com.ferreteriahuaman.security.AuthModels.Identity;
import java.math.BigDecimal;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.env.Environment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional
@EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class InventoryDatabaseTest {
 @Autowired InventoryService service;@Autowired ProductService products;@Autowired PurchaseService purchases;@Autowired CatalogService catalog;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;
 Identity actor;String unique;long category;BigDecimal n(String v){return new BigDecimal(v);}
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));unique="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();category=catalog.createCategory(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CatalogModels.CategoryInput(unique,null,null)).id();}
 Product product(String mode,String unitCode){long unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat=?",Long.class,unitCode);return products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique+mode.substring(0,1),"Producto "+mode,null,category,unit,true,n("0.001"),n("0.001"),mode,n("5"),null,"Base",n("20"),null));}
 @Test void adjustmentsUpdateStockCloseAlertsAndAreIdempotent(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("2"),n("4"),UUID.randomUUID(),List.of()));assertThat(service.alerts(unique,"ABIERTA",0,20).total()).isEqualTo(1);long reason=jdbc.queryForObject("select min(id_motivo_ajuste) from huaman.motivo_ajuste where estado='A'",Long.class);var input=new Adjustment(p.id(),"AUMENTO",n("5"),reason,"Material encontrado en revisión",UUID.randomUUID(),List.of());long id=service.adjust(actor,"INTEGRATION_ROLLBACK",input).id();assertThat(service.adjust(actor,"INTEGRATION_ROLLBACK",input).id()).isEqualTo(id);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("7.000000");assertThat(service.alerts(unique,"CERRADA",0,20).total()).isEqualTo(1);service.adjust(actor,"INTEGRATION_ROLLBACK",new Adjustment(p.id(),"DISMINUCION",n("1"),reason,"Merma registrada en revisión",UUID.randomUUID(),List.of()));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("6.000000");assertThat(service.adjustments(actor,unique,"",0,20).total()).isEqualTo(2);jdbc.execute("set constraints all immediate");}
 @Test void openingBagPreservesStockAndCreatesLooseMaterial(){var p=product("ENVASES","KGM");var bag=products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),null,new PresentationInput("Bolsa",null,n("50"),true,false,n("1"),n("1"),n("100"),null));purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("50"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique+"-B","ENVASE",n("50"),bag.id()))));long origin=purchases.existences(p.id(),0,20).items().getFirst().id();var input=new Transformation(origin,"ABRIR",List.of(),"Venta por contenido suelto",UUID.randomUUID());long id=service.transform(actor,"INTEGRATION_ROLLBACK",input).id();assertThat(service.transform(actor,"INTEGRATION_ROLLBACK",input).id()).isEqualTo(id);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("50.000000");assertThat(purchases.existences(p.id(),0,20).items()).anyMatch(u->u.condicion().equals("SUELTO")&&u.cantidadDisponible().equals("50.000000"));jdbc.execute("set constraints all immediate");}
 @Test void cutsPreserveTotalLengthAndIdentifyBothResults(){var p=product("TRAMOS","MTR");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("6"),n("2"),UUID.randomUUID(),List.of(new PhysicalUnit(unique+"-T","TRAMO",n("6"),null))));long origin=purchases.existences(p.id(),0,20).items().getFirst().id();service.transform(actor,"INTEGRATION_ROLLBACK",new Transformation(origin,"CORTAR",List.of(n("2.5"),n("3.5")),"Corte solicitado para venta",UUID.randomUUID()));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("6.000000");assertThat(purchases.existences(p.id(),0,20).items().stream().filter(u->n(u.cantidadDisponible()).signum()>0).map(u->n(u.cantidadDisponible())).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("6");jdbc.execute("set constraints all immediate");}
 @Test void countsOnlyChangeStockAfterApprovalAndRetryDoesNotDuplicate(){var p=product("GRANEL","KGM");purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("2"),UUID.randomUUID(),List.of()));var start=new Start("CATEGORIA",category,"Prueba de conteo",UUID.randomUUID());long take=service.start(actor,"INTEGRATION_ROLLBACK",start).id();assertThat(service.start(actor,"INTEGRATION_ROLLBACK",start).id()).isEqualTo(take);assertThat(service.counts(actor,take,"",0,20).total()).isEqualTo(1);var request=new Count(p.id(),n("8"),0,UUID.randomUUID(),List.of());service.count(actor,"INTEGRATION_ROLLBACK",take,request);service.count(actor,"INTEGRATION_ROLLBACK",take,request);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("10.000000");service.transition(actor,"INTEGRATION_ROLLBACK",take,"cerrar",new Transition(0,UUID.randomUUID(),null));var approve=new Transition(1,UUID.randomUUID(),"Revisión física aprobada");service.transition(actor,"INTEGRATION_ROLLBACK",take,"aprobar",approve);service.transition(actor,"INTEGRATION_ROLLBACK",take,"aprobar",approve);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("8.000000");assertThat(service.take(take).get("estado")).isEqualTo("APROBADA");assertThat(service.takes(unique,"",0,20).total()).isEqualTo(1);jdbc.execute("set constraints all immediate");}
 @Test void reopeningClearsPreviousCountsAndCancellationReleasesTake(){var p=product("GRANEL","KGM");long take=service.start(actor,"INTEGRATION_ROLLBACK",new Start("CATEGORIA",category,null,UUID.randomUUID())).id();service.count(actor,"INTEGRATION_ROLLBACK",take,new Count(p.id(),n("0"),0,UUID.randomUUID(),List.of()));service.transition(actor,"INTEGRATION_ROLLBACK",take,"cerrar",new Transition(0,UUID.randomUUID(),null));service.transition(actor,"INTEGRATION_ROLLBACK",take,"reabrir",new Transition(1,UUID.randomUUID(),"Conteo solicitado nuevamente"));assertThat(service.counts(actor,take,"",0,20).items().getFirst().get("cantidad")).isNull();service.transition(actor,"INTEGRATION_ROLLBACK",take,"anular",new Transition(2,UUID.randomUUID(),"Toma cancelada por duplicación"));assertThat(service.take(take).get("estado")).isEqualTo("ANULADA");}
 @Test void physicalAdjustmentsAndCountingPreserveExactPhysicalPlans(){var p=product("ENVASES","KGM");var bag=products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),null,new PresentationInput("Bolsa",null,n("50"),true,false,n("1"),n("1"),n("100"),null));purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("50"),n("1"),UUID.randomUUID(),List.of(new PhysicalUnit(unique+"-B","ENVASE",n("50"),bag.id()))));long reason=jdbc.queryForObject("select min(id_motivo_ajuste) from huaman.motivo_ajuste where estado='A'",Long.class);service.adjust(actor,"INTEGRATION_ROLLBACK",new Adjustment(p.id(),"AUMENTO",n("2"),reason,"Material suelto encontrado",UUID.randomUUID(),List.of(new Physical(null,"SUELTO",null,n("2")))));var units=purchases.existences(p.id(),0,20).items();long loose=units.stream().filter(u->u.condicion().equals("SUELTO")).findFirst().orElseThrow().id();long closed=units.stream().filter(u->u.condicion().equals("ENVASE")).findFirst().orElseThrow().id();service.adjust(actor,"INTEGRATION_ROLLBACK",new Adjustment(p.id(),"DISMINUCION",n("1"),reason,"Material suelto deteriorado",UUID.randomUUID(),List.of(new Physical(loose,null,null,n("1")))));long take=service.start(actor,"INTEGRATION_ROLLBACK",new Start("CATEGORIA",category,null,UUID.randomUUID())).id();service.count(actor,"INTEGRATION_ROLLBACK",take,new Count(p.id(),n("52.500000"),0,UUID.randomUUID(),List.of(new Physical(closed,null,null,n("50")),new Physical(null,"SUELTO",null,n("2.500000")))));assertThat(service.counts(actor,take,"",0,20).items().getFirst().get("plan").toString()).contains("2.500000");service.transition(actor,"INTEGRATION_ROLLBACK",take,"cerrar",new Transition(0,UUID.randomUUID(),null));service.transition(actor,"INTEGRATION_ROLLBACK",take,"aprobar",new Transition(1,UUID.randomUUID(),null));assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("52.500000");jdbc.execute("set constraints all immediate");}
}

